param([string]$Folder, [string]$Case, [string]$InnerPowerShell)
$ErrorActionPreference = 'Stop'
$env:WAC_LAUNCH_POWERSHELL = $InnerPowerShell
$env:WAC_LAUNCH_SETTINGS_PATH = Join-Path $Folder 'isolated settings.json'
$env:WAC_LAUNCH_IGNORE_SAVED_SETTINGS = '1'
$env:WAC_LAUNCH_INPUT = ''
$env:WAC_LAUNCH_INPUT_LIST_PATH = ''
$env:WAC_LAUNCH_OUTPUT_DIRECTORY = Join-Path $Folder 'out [1] & %literal% !'
$env:WAC_PROBE_RECORD = Join-Path $Folder 'record.json'
$env:WAC_PROBE_EXIT = '7'
$env:WAC_LAUNCH_PERCENT_TOKEN = 'expanded-decoy'
$unicode = ([char]0x00e4).ToString() + [char]0x00f6 + [char]0x00c5
$bat = Join-Path $Folder 'WinAudioClean.bat'
switch ($Case) {
    'single' { & $bat (Join-Path $Folder ("speaker "+$unicode+" [draft] & guest.wav")) }
    'multiple' { & $bat @((Join-Path $Folder "speaker's (draft) & guest.wav"), (Join-Path $Folder ("meeting "+$unicode+".wav")), (Join-Path $Folder 'name & echo WAC_UNEXPECTED_COMMAND.wav')) }
    'percent-reject' { & $bat (Join-Path $Folder 'meeting %WAC_LAUNCH_PERCENT_TOKEN%.wav') }
    'bang-reject' { & $bat (Join-Path $Folder 'meeting !important!.wav') }
    'manifest' {
        $env:WAC_LAUNCH_INPUT_LIST_PATH = Join-Path $Folder 'inputs %literal% ! [1].json'
        & $bat /manifest
    }
    'unattended-single' {
        $env:WAC_LAUNCH_INPUT = Join-Path $Folder 'meeting %WAC_LAUNCH_PERCENT_TOKEN% !important! & [1].wav'
        & $bat /unattended Raw
    }
    'unattended-manifest' {
        $env:WAC_LAUNCH_INPUT_LIST_PATH = Join-Path $Folder 'inputs %literal% ! [1].json'
        & $bat /unattended Zoom
    }
    'empty' { & $bat }
}
exit $LASTEXITCODE

param([string]$inputPath, [string[]]$InputPaths, [string]$InputListPath,
    [string]$OutputDirectory, [string]$Mode, [string]$SettingsPath,
    [switch]$IgnoreSavedSettings, [switch]$NonInteractive)
$inputs = [string[]]@(
    if ($InputListPath) { ([IO.File]::ReadAllText($InputListPath, [Text.Encoding]::UTF8) | ConvertFrom-Json).inputs }
    elseif ($PSBoundParameters.ContainsKey('InputPaths')) { $InputPaths }
    else { $inputPath }
)
$record = [ordered]@{ host = [string]$PSVersionTable.PSVersion; inputs = $inputs; boundKeys = @($PSBoundParameters.Keys)
    inputListPath = $InputListPath; outputDirectory = $OutputDirectory; mode = $Mode; settingsPath = $SettingsPath
    ignoreSavedSettings = [bool]$IgnoreSavedSettings; nonInteractive = [bool]$NonInteractive
    originalCmd = $env:WAC_LAUNCH_COMMAND_LINE; argumentCount = $env:WAC_LAUNCH_COUNT }
[IO.File]::WriteAllText($env:WAC_PROBE_RECORD, ($record | ConvertTo-Json -Depth 6), [Text.UTF8Encoding]::new($false))
exit ([int]$env:WAC_PROBE_EXIT)

param([string]$OutputFolder)
$ErrorActionPreference = 'Stop'
$repo = '<repo>'
$unicode = ([char]0x00e4).ToString() + [char]0x00f6 + [char]0x00c5
$shells = [ordered]@{ ps51 = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"; ps7 = (Get-Command pwsh).Source }
if (-not $OutputFolder) { $OutputFolder = Join-Path $repo ('.wac-local\WAC-M3-02\transport-final-' + [guid]::NewGuid().ToString('N')) }
[void][IO.Directory]::CreateDirectory($OutputFolder)
$rows = @()
$started = [DateTime]::UtcNow
foreach ($outer in $shells.Keys) {
    foreach ($inner in $shells.Keys) {
        foreach ($case in @('single','multiple','percent-reject','bang-reject','manifest','unattended-single','unattended-manifest','empty')) {
            $folder = Join-Path $OutputFolder ($outer + '-' + $inner + '-' + $case)
            [void][IO.Directory]::CreateDirectory($folder)
            [IO.File]::Copy((Join-Path $repo 'WinAudioClean.bat'), (Join-Path $folder 'WinAudioClean.bat'))
            [IO.File]::Copy((Join-Path $repo 'WinAudioClean.Launcher.ps1'), (Join-Path $folder 'WinAudioClean.Launcher.ps1'))
            [IO.File]::Copy((Join-Path $repo '.wac-local\WAC-M3-02\LauncherMainProbe.ps1'), (Join-Path $folder 'WinAudioClean.ps1'))
            $manifestInputs = @((Join-Path $folder ("speaker's " + $unicode + '.wav')), (Join-Path $folder 'literal %WAC_LAUNCH_PERCENT_TOKEN% !important! & [1].wav'))
            [IO.File]::WriteAllText((Join-Path $folder 'inputs %literal% ! [1].json'), (@{schemaVersion=1; inputs=$manifestInputs} | ConvertTo-Json -Depth 4), [Text.UTF8Encoding]::new($false))
            $info = [Diagnostics.ProcessStartInfo]::new()
            $info.FileName = $shells[$outer]
            $info.Arguments = '-NoLogo -NoProfile -ExecutionPolicy Bypass -File "' + (Join-Path $repo '.wac-local\WAC-M3-02\Invoke-TransportProbe.ps1') + '" -Folder "' + $folder + '" -Case ' + $case + ' -InnerPowerShell "' + $shells[$inner] + '"'
            $info.UseShellExecute = $false
            $info.RedirectStandardInput=$true; $info.RedirectStandardOutput=$true; $info.RedirectStandardError=$true
            $process = [Diagnostics.Process]::new(); $process.StartInfo = $info
            [void]$process.Start()
            $process.StandardInput.WriteLine(''); $process.StandardInput.Close()
            $stdoutTask=$process.StandardOutput.ReadToEndAsync(); $stderrTask=$process.StandardError.ReadToEndAsync()
            if (-not $process.WaitForExit(30000)) { $process.Kill(); throw "Probe timed out: $outer/$inner/$case" }
            $stdout=$stdoutTask.GetAwaiter().GetResult(); $stderr=$stderrTask.GetAwaiter().GetResult(); $exitCode=$process.ExitCode
            $process.Dispose()
            [IO.File]::WriteAllText((Join-Path $folder 'stdout.txt'),$stdout,[Text.UTF8Encoding]::new($false))
            [IO.File]::WriteAllText((Join-Path $folder 'stderr.txt'),$stderr,[Text.UTF8Encoding]::new($false))
            $expectedInputs = @()
            switch ($case) {
                'single' { $expectedInputs = @((Join-Path $folder ('speaker '+$unicode+' [draft] & guest.wav'))) }
                'multiple' { $expectedInputs = @((Join-Path $folder "speaker's (draft) & guest.wav"), (Join-Path $folder ('meeting '+$unicode+'.wav')), (Join-Path $folder 'name & echo WAC_UNEXPECTED_COMMAND.wav')) }
                'manifest' { $expectedInputs = $manifestInputs }
                'unattended-manifest' { $expectedInputs = $manifestInputs }
                'unattended-single' { $expectedInputs = @((Join-Path $folder 'meeting %WAC_LAUNCH_PERCENT_TOKEN% !important! & [1].wav')) }
            }
            $expectedExit = if ($expectedInputs.Count) { 7 } else { 2 }
            $recordPath=Join-Path $folder 'record.json'
            $failures=@()
            if ($exitCode -ne $expectedExit) { $failures += 'exit' }
            if ([IO.File]::Exists($recordPath) -ne ($expectedInputs.Count -gt 0)) { $failures += 'recordPresence' }
            if ([IO.File]::Exists($recordPath)) {
                $record = [IO.File]::ReadAllText($recordPath,[Text.Encoding]::UTF8) | ConvertFrom-Json
                if (@($record.inputs).Count -ne $expectedInputs.Count) { $failures += 'inputCount' }
                for ($index=0; $index -lt $expectedInputs.Count; $index++) {
                    if ($record.inputs[$index] -cne $expectedInputs[$index]) { $failures += ('input'+$index) }
                }
                if (($inner -eq 'ps51' -and $record.host -notlike '5.1.*') -or ($inner -eq 'ps7' -and $record.host -notlike '7.*')) { $failures += 'actualHost' }
                if ($record.ignoreSavedSettings -ne $true -or $record.settingsPath -cne (Join-Path $folder 'isolated settings.json')) { $failures += 'settingsIsolation' }
                if ($record.nonInteractive -ne $case.StartsWith('unattended')) { $failures += 'nonInteractive' }
                $expectedKey = if ($case -like '*manifest*') { 'InputListPath' } elseif ($case -eq 'multiple') { 'InputPaths' } else { 'inputPath' }
                if ($record.boundKeys -notcontains $expectedKey) { $failures += 'inputBinding' }
                if ($case -like 'unattended*' -and $stdout -match 'Press any key') { $failures += 'unexpectedPause' }
                if ($case -notlike 'unattended*' -and $stdout -notmatch 'Press any key') { $failures += 'missingPause' }
            }
            $rows += [ordered]@{ outer=$outer; inner=$inner; case=$case; exitCode=$exitCode; expectedExit=$expectedExit; exactPayloadPass=($failures.Count -eq 0); failures=$failures; command=($info.FileName+' '+$info.Arguments); folder=$folder }
            if ($failures.Count) { Write-Host "FAIL $outer/$inner/$case : $($failures -join ',')" } else { Write-Host "PASS $outer/$inner/$case" }
        }
    }
}
$result=[ordered]@{ startedUtc=$started.ToString('o'); finishedUtc=[DateTime]::UtcNow.ToString('o'); sourceHashes=@{ bat=(Get-FileHash (Join-Path $repo 'WinAudioClean.bat')).Hash; launcher=(Get-FileHash (Join-Path $repo 'WinAudioClean.Launcher.ps1')).Hash; probe=(Get-FileHash (Join-Path $repo '.wac-local\WAC-M3-02\Invoke-TransportProbe.ps1')).Hash; runner=(Get-FileHash $PSCommandPath).Hash }; cases=$rows; passed=@($rows|Where-Object exactPayloadPass).Count; failed=@($rows|Where-Object {-not $_.exactPayloadPass}).Count }
[IO.File]::WriteAllText((Join-Path $OutputFolder 'results.json'),($result|ConvertTo-Json -Depth 7),[Text.UTF8Encoding]::new($false))
Write-Host ('Evidence: '+$OutputFolder)
if ($result.failed) { exit 1 }
exit 0
